import{_ as s,o as a,c as t,j as e,a as n}from"./chunks/framework.DJo0M80U.js";const f=JSON.parse('{"title":"screen 对象","description":"JavaScript中有几个对象在编程中用处不大，而screen对象就是其中之一。screen对象基本上只用来表明客户端的能力，其中包括浏览器窗口外部的显示器的信息，如像素宽度和高度等。每个浏览器中的screen对象都包含着各不相同的属性，下表列出了所有属性及支持相应属性的浏览器。","frontmatter":{"title":"screen 对象","date":"2026-08-11T00:00:00.000Z","categories":["JavaScript 系统教程"],"tags":["JavaScript","前端","教程","OneNote","浏览器与 Web API"],"description":"JavaScript中有几个对象在编程中用处不大，而screen对象就是其中之一。screen对象基本上只用来表明客户端的能力，其中包括浏览器窗口外部的显示器的信息，如像素宽度和高度等。每个浏览器中的screen对象都包含着各不相同的属性，下表列出了所有属性及支持相应属性的浏览器。","sidebarWeight":7,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/b-原生js/BOM/screen 对象.md"},"headers":[],"relativePath":"posts/JavaScript系统教程/04-浏览器与 Web API/screen 对象.md","filePath":"posts/JavaScript系统教程/04-浏览器与 Web API/screen 对象.md"}'),c={name:"posts/JavaScript系统教程/04-浏览器与 Web API/screen 对象.md"};function o(i,r,l,d,p,u){return a(),t("div",null,[...r[0]||(r[0]=[e("div",null,[e("h1",{id:"screen-对象",tabindex:"-1"},[n("screen 对象 "),e("a",{class:"header-anchor",href:"#screen-对象","aria-label":'Permalink to "screen 对象"'},"​")]),e("blockquote",null,[e("p",null,"本节目标：理解“screen 对象”的核心思路，并能把它用于实际开发或面试表达。")]),e("blockquote",null,[e("p",null,"说明：原 OneNote 中有图片引用，但图片未包含在导出目录中；本页保留了可用的文字与代码内容。 JavaScript中有几个对象在编程中用处不大，而screen对象就是其中之一。screen对象基本上只用来表明客户端的能力，其中包括浏览器窗口外部的显示器的信息，如像素宽度和高度等。每个浏览器中的screen对象都包含着各不相同的属性，下表列出了所有属性及支持相应属性的浏览器：")]),e("p",null,"这些信息经常集中出现在测定客户端能力的站点限踪工具中，但通常不会用于影响功能。不过，有时候也可能会用到其中的信息来调整浏览器窗口大小，使其占据屏幕的可用空间，例如： window.resizeTo(screen.availwidth, screen.avalLHeight); 前面曾经提到过，许多浏览器都会禁用调整浏览器窗口大小的能力，因此上面这行代码不一定在所有环境下都有效。"),e("p",null,"涉及移动设备的屏幕大小时，情况有点不一样。运行iOS的设备始终会像是把设备竖着拿在手里一样，因此返回的值是768 x 102，而Android设备则会相应调用screen.width和screen.height的值。")],-1)])])}const h=s(c,[["render",o]]);export{f as __pageData,h as default};
